import assert from 'node:assert/strict';import{mkdirSync,writeFileSync,readFileSync}from'node:fs';import{chromium,webkit}from'playwright';
import{displayedChapterCollections,chapterHash}from'../lib/practice-chapters.ts';
const base=process.env.KLINK_TEST_BASE||'http://127.0.0.1:18996',out=process.env.KLINK_TEST_OUTPUT||'outputs/listen-photo-fit-20261101/local';mkdirSync(out,{recursive:true});
const nativeOnly=Boolean(process.env.KLINK_TEST_NATIVE_ONLY),shortOnly=Boolean(process.env.KLINK_TEST_SHORT_ONLY);
const cases=['listen','read'].flatMap(activity=>['alfa-a','alfa-b'].flatMap(level=>displayedChapterCollections(activity,{level,help:'practice'}).map(row=>({activity,level,row})))),checks=[],native=[],errors=[];
const route=c=>chapterHash({chapter:c.activity==='listen'?'listening':'words',activity:c.activity,collection:c.row.id,level:c.level,help:'practice'});
const pictured=cases.find(c=>c.activity==='listen'&&c.row.id==='groep-10.alfa-b~words-1');assert.equal(cases.length,119);
async function metrics(p){return p.evaluate(()=>{
 const stage=document.querySelector('.cp-exercise-stage'),r=stage.getBoundingClientRect(),foot=document.querySelector('.cp-exercise-feedback').getBoundingClientRect(),nav=document.querySelector('.learner-nav'),bottom=nav.offsetHeight&&getComputedStyle(nav).position==='fixed'?nav.getBoundingClientRect().top:innerHeight;
 const buttons=[...document.querySelectorAll('.cp-task-card > .cp-choice-grid > button')],images=[...document.querySelectorAll('.cp-task-card > .cp-choice-grid img')];
 return{stageFits:stage.scrollHeight<=stage.clientHeight+2&&stage.scrollTop===0,allChoicesFit:buttons.every(e=>{const q=e.getBoundingClientRect();return q.top>=r.top-1&&q.bottom<=r.bottom+1&&q.width>=48&&q.height>=48;}),allPhotosFit:images.every(e=>{const q=e.getBoundingClientRect();return e.naturalWidth>0&&getComputedStyle(e).objectFit==='contain'&&q.top>=r.top-1&&q.bottom<=r.bottom+1&&q.height>=32;}),footerFits:foot.bottom<=bottom+1,photoCount:images.length,noHorizontalScroll:document.documentElement.scrollWidth<=innerWidth+1,oldProgressPreserved:JSON.parse(localStorage.getItem('klink.taalroute.attempts.v1')||'[]').some(a=>a.existing===true)};
});}
function check(m,label){for(const k of['stageFits','allChoicesFit','allPhotosFit','footerFits','noHorizontalScroll','oldProgressPreserved'])assert.equal(m[k],true,label+' '+k);assert(m.photoCount>0,label+' photos remain visible');}
await Promise.all(Object.entries({chromium,webkit}).map(async([engine,type])=>{const b=await type.launch();try{
 for(const[width,height]of(nativeOnly||shortOnly?[]:[[1366,768],[390,844]])){
  const p=await b.newPage({viewport:{width,height}});p.on('pageerror',e=>errors.push(engine+': '+e.message));await p.addInitScript(()=>{if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.Audio=class extends EventTarget{play(){this.t=setTimeout(()=>this.dispatchEvent(new Event('ended')),5);return Promise.resolve();}pause(){clearTimeout(this.t);}};});
  for(const c of cases){console.log('case',engine,width,c.activity,c.row.id);await p.goto(base+'/#learner/home');await p.locator('.cp-home').waitFor();await p.evaluate(c=>{const e=c.row.exercises.find(e=>e.options?.some(o=>o.image?.src));localStorage.setItem(`klink.group.v1:chapter:${c.activity}:${c.row.id}:${c.activity}`,JSON.stringify({version:1,done:false,exerciseId:e.exerciseId}));},c);await p.goto(base+'/'+route(c));await p.locator('.cp-choice-grid img, .cp-choice-grid .cp-word-placeholder').first().waitFor();await p.waitForFunction(()=>[...document.querySelectorAll('.cp-choice-grid img')].every(e=>e.complete&&e.naturalWidth>0));await p.waitForTimeout(100);const m=await metrics(p);check(m,engine+' '+width+' '+c.row.id+' '+c.activity);checks.push({engine,width,height,id:c.row.id,activity:c.activity,...m});}
  await p.close();console.log(engine,width,119,'rounds passed');
 }
 for(const[width,height]of(nativeOnly?[]:[[1686,885],[1366,768],[390,844],[320,568],[740,390],[1366,600]]))for(const colorScheme of['light','dark']){
  const p=await b.newPage({viewport:{width,height},hasTouch:true,colorScheme});p.on('pageerror',e=>errors.push(engine+': '+e.message));await p.addInitScript(()=>localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]'));
  await p.goto(base+'/'+route(pictured));await p.locator('.cp-choice-grid img, .cp-choice-grid .cp-word-placeholder').first().waitFor();await p.waitForTimeout(150);const m=await metrics(p);check(m,engine+' pictured '+width);checks.push({engine,width,height,colorScheme,id:pictured.row.id,activity:'listen',...m});
  if(engine==='chromium'&&colorScheme==='light')await p.screenshot({path:`${out}/${width}-${height}.png`});
  await p.goto(base+'/#learner/home');await p.locator('.cp-home').waitFor();assert(await p.locator('.taalroute-header').isVisible());assert(await p.locator('.learner-nav').isVisible());await p.close();
 }
 if(nativeOnly)checks.push(...JSON.parse(readFileSync(`${out}/geometry-${engine}.json`)));if(shortOnly)checks.push(...JSON.parse(readFileSync(`${out}/geometry-${engine}.json`)).filter(c=>!c.colorScheme));if(!nativeOnly)writeFileSync(`${out}/geometry-${engine}.json`,JSON.stringify(checks.filter(c=>c.engine===engine)));
 const p=await b.newPage({viewport:{width:390,height:844},hasTouch:true});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(()=>{if(!localStorage.getItem('klink.taalroute.attempts.v1'))localStorage.setItem('klink.taalroute.attempts.v1','[{"existing":true}]');window.ended=[];window.addEventListener('klink-audio-source',e=>{const a=e.detail;a.volume=0;if(a.observed)return;a.observed=true;a.addEventListener('ended',()=>window.ended.push(a.src));});});
 await p.goto(base+'/'+route(pictured));const root=p.locator('[data-exercise-id]');await root.waitFor();const id=await root.getAttribute('data-exercise-id'),exercise=pictured.row.exercises.find(e=>e.exerciseId===id);assert(exercise);
 await p.locator('[data-practice-automatic]').tap();await p.waitForFunction(()=>[...document.querySelectorAll('.cp-choice-grid>button')].every(b=>!b.disabled));
 await root.locator('h3').focus();await p.keyboard.press('Space');await p.waitForFunction(()=>window.ended.length>0);await p.waitForFunction(()=>[...document.querySelectorAll('.cp-choice-grid>button')].every(b=>!b.disabled));
 const correct=exercise.options.findIndex(o=>exercise.answer.correctOptionIds.includes(o.id));await p.locator('.cp-choice-grid>button').nth(correct).focus();await p.keyboard.press('Enter');await p.waitForFunction(()=>document.querySelector('[data-practice-ready="true"]'));await p.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);check(await metrics(p),engine+' correct feedback');
 let stored=await p.evaluate(()=>Object.fromEntries(Object.entries(localStorage).filter(([k])=>k.includes('attempt')||k.startsWith('klink.group.'))));assert(Object.keys(stored).length>1,'Existing progress handlers store the answer');await p.keyboard.press('ArrowRight');await p.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.getAttribute('data-exercise-id')!==id,id);await p.waitForFunction(()=>[...document.querySelectorAll('.cp-choice-grid>button')].every(b=>!b.disabled));await p.keyboard.press('ArrowLeft');await p.waitForFunction(id=>document.querySelector('[data-exercise-id]')?.getAttribute('data-exercise-id')===id,id);
 stored=await p.evaluate(()=>Object.fromEntries(Object.entries(localStorage).filter(([k])=>k.includes('attempt')||k.startsWith('klink.group.'))));await p.reload();await p.locator('.cp-choice-grid img, .cp-choice-grid .cp-word-placeholder').first().waitFor();for(const[k,v]of Object.entries(stored))assert.deepEqual(JSON.parse(await p.evaluate(k=>localStorage.getItem(k),k)),JSON.parse(v));
 native.push({engine,nativePlayback:true,enter:true,arrows:true,touch:true,progressPreserved:true});await p.close();
 }finally{await b.close();}}));
assert.deepEqual(errors,[]);writeFileSync(out+'/checks.json',JSON.stringify({checks,native,errors},null,2));console.log('PASS',checks.length,'photo layouts and',native.length,'native audio/keyboard/progress checks');
